import java.nio.charset.StandardCharsets.UTF_8
import java.nio.file.Files
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.json.Json

@Serializable data class Nota(val texto: String)

fun copiaJson(texto: String): String {
    val ruta = Files.createTempFile("nota-", ".json")
    try {
        val serializado = Json.encodeToString(Nota(texto))
        Files.writeString(ruta, serializado, UTF_8)
        val leido = Files.readString(ruta, UTF_8)
        return Json.decodeFromString<Nota>(leido).texto
    } finally {
        Files.deleteIfExists(ruta)
    }
}
