import { useEffect, useState } from "react";

export function TituloRemoto({ url }) {
  const [estado, setEstado] = useState({ url: null, tipo: "cargando" });
  const visible = estado.url === url ? estado : { tipo: "cargando" };

  useEffect(() => {
    const controller = new AbortController();
    let activa = true;
    async function cargar() {
      try {
        const respuesta = await fetch(url, { signal: controller.signal });
        if (!respuesta.ok) throw new Error("HTTP");
        const datos = await respuesta.json();
        if (typeof datos.title !== "string") throw new Error("Formato");
        if (activa) setEstado({ url, tipo: "dato", titulo: datos.title });
      } catch (error) {
        if (activa && error.name !== "AbortError") {
          setEstado({ url, tipo: "error" });
        }
      }
    }
    setEstado({ url, tipo: "cargando" });
    void cargar();
    return () => { activa = false; controller.abort(); };
  }, [url]);

  if (visible.tipo === "cargando") return <p>Cargando</p>;
  if (visible.tipo === "error") return <p role="alert">Error</p>;
  return <p>{visible.titulo}</p>;
}
