[javascript]
// Cliente: #salida tiene aria-live="polite".
const formulario = document.querySelector("#formulario");
const entrada = document.querySelector("#mensaje");
const salida = document.querySelector("#salida");
formulario.addEventListener("submit", async (evento) => {
  evento.preventDefault();
  if (entrada.value.trim() === "") {
    entrada.setCustomValidity("Escribe un mensaje.");
    entrada.reportValidity();
    return;
  }
  entrada.setCustomValidity("");
  const respuesta = await fetch("/comentarios", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ mensaje: entrada.value })
  });
  if (!respuesta.ok) {
    salida.textContent = "No se pudo guardar el mensaje.";
    return;
  }
  salida.textContent = entrada.value;
});

// Servidor Node.js con Express y express.json() configurados.
app.post("/comentarios", (req, res) => {
  const mensaje = req.body?.mensaje;
  if (typeof mensaje !== "string" || mensaje.trim() === "") {
    return res.status(400).json({ error: "Escribe un mensaje." });
  }
  // Guardar mensaje después de la validación.
  return res.sendStatus(204);
});
